package com.pousada.infrastructure;

import com.pousada.domain.RatePlan;
import com.pousada.domain.Reservation;
import com.pousada.domain.ReservationStatus;

import java.sql.Connection;
import java.sql.Date;
import java.sql.ResultSet;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class ReservationRepository {
    public Reservation save(Reservation reservation) throws Exception {
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement()) {

            String sql = String.format("""
                INSERT INTO reservations (
                    room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
                    guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund
                ) VALUES (
                    %d, '%s', '%s', '%s', '%s', '%s',
                    %d, '%s', %d, %.2f, %.2f, %.2f, '%s', %.2f, NULL
                ) RETURNING id
                """,
                reservation.getRoomNumber(),
                escapeSql(reservation.getGuestName()),
                escapeSql(reservation.getGuestEmail()),
                escapeSql(reservation.getGuestCpf()),
                reservation.getCheckIn(),
                reservation.getCheckOut(),
                reservation.getGuests(),
                reservation.getRatePlan().getDisplayName(),
                reservation.getNights(),
                reservation.getSubtotal(),
                reservation.getDiscount(),
                reservation.getTotal(),
                reservation.getStatus().name()
            );

            try (ResultSet rs = stmt.executeQuery(sql)) {
                if (rs.next()) {
                    reservation.setId(rs.getLong("id"));
                }
            }
        }
        return reservation;
    }

    public Optional<Reservation> findById(long id) throws Exception {
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT * FROM reservations WHERE id = " + id)) {

            if (rs.next()) {
                return Optional.of(mapResultSetToReservation(rs));
            }
        }
        return Optional.empty();
    }

    public void update(Reservation reservation) throws Exception {
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement()) {

            String refundValue = reservation.getRefund() != null ? 
                String.format("%.2f", reservation.getRefund()) : "NULL";

            String sql = String.format("""
                UPDATE reservations
                SET status = '%s', amount_paid = %.2f, refund = %s
                WHERE id = %d
                """,
                reservation.getStatus().name(),
                reservation.getAmountPaid(),
                refundValue,
