package com.pousada.infrastructure;

import com.pousada.domain.Message;
import com.pousada.domain.MessageChannel;

import java.sql.Connection;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class MessageRepository {
    public Message save(Message message) throws Exception {
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement()) {

            String sql = String.format("""
                INSERT INTO messages (channel, recipient, subject, body)
                VALUES ('%s', '%s', '%s', '%s') RETURNING id
                """,
                message.getChannelString(),
                escapeSql(message.getTo()),
                escapeSql(message.getSubject()),
                escapeSql(message.getBody())
            );

            try (ResultSet rs = stmt.executeQuery(sql)) {
                if (rs.next()) {
                    message.setId(rs.getLong("id"));
                }
            }
        }
        return message;
    }

    public List<Message> findAll() throws Exception {
        List<Message> messages = new ArrayList<>();
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery("SELECT id, channel, recipient, subject, body FROM messages")) {

            while (rs.next()) {
                Message message = new Message(
                    MessageChannel.valueOf(rs.getString("channel")),
                    rs.getString("recipient"),
                    rs.getString("subject"),
                    rs.getString("body")
                );
                message.setId(rs.getLong("id"));
                messages.add(message);
            }
        }
        return messages;
    }

    private String escapeSql(String value) {
        return value.replace("'", "''");
    }
}

